parameters.jsCode:
const execution = $json.execution ?? {};
const workflow = $json.workflow ?? {};
const error = execution.error ?? {};
return [{
  json: {
    workflowId: workflow.id ?? null,
    workflowName: workflow.name ?? 'unknown',
    executionId: execution.id ?? null,
    executionUrl: execution.url ?? null,
    lastNode: execution.lastNodeExecuted ?? null,
    message: typeof error.message === 'string' ? error.message : 'Unhandled n8n workflow error',
    stack: typeof error.stack === 'string' ? error.stack.slice(0, 4000) : null,
  },
}];

